 const shortDate=d=>new Intl.DateTimeFormat('fr-FR',{weekday:'short',day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
 screen('booking',`<div class="hero"><div class="eyebrow">Votre rendez-vous</div><h1>Choisissez votre date et votre piste</h1><p>Disponibilités calculées selon vos prestations · Heure de Tunis.</p></div><section class="card"><h2>Prestations sélectionnées</h2>${ss.map(x=>`<div class="row between"><span>${esc(x.name)} · ${dur(x.duration)}</span><b>${money(x.price)}</b></div>`).join('')}<hr><div class="row between"><strong>Total · ${dur(duration)}</strong><strong class="price">${money(ss.reduce((n,x)=>n+x.price,0))}</strong></div></section><form id="booking" class="card stack"><div class="row between"><h2>1. Choisir une date</h2><div class="row"><button type="button" class="outline small" id="prevWeek" aria-label="Sept jours précédents">←</button><button type="button" class="outline small" id="todayWeek">Aujourd’hui</button><button type="button" class="outline small" id="nextWeek" aria-label="Sept jours suivants">→</button></div></div><label>Aller à une autre date<input id="date" type="date" min="${today}" value="${today}" required></label><div id="weekLabel" class="muted"></div><div id="calendarDays" class="booking-days" aria-label="Disponibilités par jour">Chargement…</div><div class="row between"><h2>2. Choisir une heure et une piste</h2><button type="button" id="refreshSlots" class="outline small">Actualiser</button></div><div id="dayHeading" class="muted"></div><div id="slots" class="booking-lanes"></div><div id="suggest" class="notice">Sélectionnez un créneau libre.</div><h2>3. Informations du véhicule</h2><label>Choisir un véhicule<select id="bookingCarChoice">${(session.customer?.vehicles||[]).map((v,i)=>`<option value="${i}">${esc(v.model)} · ${esc(v.plate)}</option>`).join('')}<option value="new">+ Ajouter un autre véhicule</option></select></label><div id="bookingCarFields">${vehicleFields(session.customer||{},'bookingVehicle')}</div><p class="muted">Le véhicule choisi sera associé à la réservation et enregistré dans votre garage.</p><label>Remarque (optionnel)<textarea id="notes" placeholder="Indications particulières…"></textarea></label><div class="error hidden" id="error"></div><button id="confirm" class="primary" type="submit" disabled>Confirmer la réservation</button><button type="button" id="back" class="outline">Modifier les prestations</button></form>`);
 let from=today,chosenDate=today,choice=null,days=[],loading=false,submitting=false;const cars=session.customer?.vehicles||[];const renderCar=()=>{const v=cars[Number(val('#bookingCarChoice'))];$('#bookingCarFields').innerHTML=vehicleFields(v?{vehicle_model:v.model,vehicle_plate:v.plate}: {},'bookingVehicle')};$('#bookingCarChoice').onchange=renderCar;if(cars.length)renderCar();
