const status=r=>`<span class="tag ${r.status==='cancelled'?'cancelled':''}">${r.status==='cancelled'?'Annulée':'Confirmée'}</span>`;
function receipt(rs){const w=window.open('','_blank');if(!w)return toast('Autorisez les fenêtres pop-up pour imprimer les reçus.');w.document.write(`<!doctype html><html lang="fr"><meta charset="utf-8"><title>Reçu Eco’Lav</title><style>body{font:14px system-ui;color:#172b20;margin:30px}article{max-width:620px;margin:0 auto 30px;border:1px solid #ddd;padding:22px;break-inside:avoid}h1{color:#087d43}table{width:100%;border-collapse:collapse}td{padding:8px;border-bottom:1px solid #ddd}@media print{button{display:none}body{margin:0}article{border:0;break-after:page}article:last-child{break-after:auto}}</style><button id="receiptPrint">Imprimer / PDF</button>${rs.map(r=>`<article><img src="${location.origin}/brand-logo.png" alt="Logo" width="84" height="84"><h1>L’Expert Eco’Lav</h1><p>Rue Taher Ben Fraj, Hammamet · 54 459 463</p><h2>Reçu n° ${r.id}</h2><p>${esc(r.name)} · ${esc(r.phone)}<br>Rendez-vous : ${esc(r.date)} à ${time(r.start)} – ${time(r.start+r.duration)} · Piste ${r.lane}<br>Réservé le : ${esc(created(r.created_at))}<br>Véhicule : ${esc(r.vehicle||'—')}<br>Statut : ${r.status==='cancelled'?'Annulée':'Confirmée'}</p><table>${r.items.map(s=>`<tr><td>${esc(s.name)}</td><td>${dur(s.duration)}</td><td>${money(s.price)}</td></tr>`).join('')}<tr><td><b>Total</b></td><td>${dur(r.duration)}</td><td><b>${money(r.total)}</b></td></tr></table><p>Remarque : ${esc(r.notes||'—')}</p></article>`).join('')}</html>`);w.document.close();w.document.getElementById('receiptPrint').addEventListener('click',()=>w.print());w.opener=null;w.focus()}
function washDetails(r){
 if(!r.wash_started_at)return '';
 const remaining=Math.max(0,Math.ceil((Date.parse(r.wash_eta_at)-Date.now())/60000));
 return `<div class="notice stack" style="margin:10px 0;gap:5px"><strong>${r.wash_finished_at?'Lavage terminé':r.status==='cancelled'?'Lavage interrompu':'Lavage en cours'}</strong><div>Début réel : ${esc(created(r.wash_started_at))}</div>${r.wash_finished_at?`<div>Fin réelle : ${esc(created(r.wash_finished_at))}</div>`:r.status==='cancelled'?'':`<div>Fin estimée : ${esc(created(r.wash_eta_at))}</div><b>${remaining?remaining+' min restantes (estimation)':'Fin estimée dépassée · en attente de confirmation'}</b>`}<small>Dernière mise à jour : ${esc(created(r.wash_updated_at))}</small></div>`;
}
function washControls(r){
 if(r.status!=='confirmed'||r.wash_finished_at)return '';
 return `<div class="stack" style="gap:6px;margin-top:8px">${r.wash_started_at?`<button class="small outline" data-wash-remaining="${r.id}">Temps restant</button><button class="small primary" data-wash-finish="${r.id}">Lavage terminé</button>`:`<button class="small primary" data-wash-start="${r.id}">Démarrer le lavage</button>`}</div>`;
}
function washAction(r,action){
 if(!r)return;
 openModal(action==='start'?'Démarrer le lavage':action==='remaining'?'Notifier le temps restant':'Terminer le lavage',`<p>Réservation n° ${r.id} · ${esc(r.name)} · ${esc(r.vehicle)}</p><p>La date et l’heure de Tunis seront enregistrées automatiquement.</p><form id="washForm" class="stack">${action==='finish'?'<p>Confirmer que le véhicule est prêt ?</p>':`<label>Temps restant estimé (minutes)<input id="washMinutes" type="number" min="1" max="1440" required value="${action==='start'?r.duration:Math.max(1,Math.ceil((Date.parse(r.wash_eta_at)-Date.now())/60000))}"></label>`}<div class="error hidden" id="washError"></div><button class="primary" type="submit">Confirmer et notifier le client</button></form>`);
 const form=$('#washForm');form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('button');if(btn.disabled)return;btn.disabled=true;try{const result=await api('admin/wash','POST',{id:r.id,action,minutes:action==='finish'?0:Number(val('#washMinutes'))});if(form.isConnected){closeModal();await loadDay();toast(result.subscribers?'Suivi enregistré · notification demandée.':'Suivi enregistré · client sans notification activée.')}}catch(e){if(form.isConnected)err(e,$('#washError'))}finally{btn.disabled=false}};
}
async function clientPushSettings(){
 openModal('Notifications de lavage',`<p>Recevez les alertes de début, de temps restant et de fin de lavage. Sur iPhone, installez l’application depuis Safari sur l’écran d’accueil.</p><div id="clientPushState" class="notice">Autorisez les notifications sur cet appareil.</div><div class="row" style="flex-wrap:wrap"><button id="clientPushEnable" class="primary">Activer / synchroniser</button><button id="clientPushDisable" class="outline">Désactiver</button><button id="clientPushTest" class="outline">Envoyer un test</button></div>`);
 const state=$('#clientPushState'),on=$('#clientPushEnable'),off=$('#clientPushDisable'),test=$('#clientPushTest');const show=t=>{if(state.isConnected)state.textContent=t};
 if(!window.isSecureContext||!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window)){show('Notifications indisponibles sur ce navigateur. Consultez Mes réservations pour le suivi.');on.disabled=off.disabled=test.disabled=true;return}
 on.onclick=async()=>{on.disabled=off.disabled=true;try{if(await Notification.requestPermission()!=='granted')throw Error('Autorisation refusée. Vérifiez les paramètres du téléphone.');await registerPushWorker();const reg=await pushTimeout(navigator.serviceWorker.ready,10000,'Service de notification indisponible.');const key=Uint8Array.from(atob(meta.vapid.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(meta.vapid.length/4)*4,'=')),c=>c.charCodeAt(0));const sub=await reg.pushManager.getSubscription()||await pushTimeout(reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key}),18000,'Abonnement impossible.');await api('client/push','POST',sub.toJSON());show('Notifications activées sur cet appareil. Vous pouvez envoyer un test.');const card=$('#clientNotifyCard');if(card){card.hidden=true;card.style.display='none'}}catch(e){show(e.message)}finally{on.disabled=off.disabled=false}};
 test.onclick=async()=>{test.disabled=true;try{const reg=await navigator.serviceWorker.getRegistration('/');const sub=await reg?.pushManager.getSubscription();if(!sub)throw Error('Activez d’abord les notifications.');const r=await api('client/push-test','POST',{endpoint:sub.endpoint});show(r.sent?'Notification transmise au service push. Vérifiez votre téléphone.':'Envoi impossible. Réactivez les notifications et réessayez.')}catch(e){show(e.message)}finally{test.disabled=false}};
 off.onclick=async()=>{on.disabled=off.disabled=true;try{const reg=await navigator.serviceWorker.getRegistration('/');const sub=await reg?.pushManager.getSubscription();if(sub){await api('client/push','DELETE',{endpoint:sub.endpoint});await sub.unsubscribe()}show('Notifications désactivées.');const card=$('#clientNotifyCard');if(card){card.hidden=false;card.style.display=''}}catch(e){show(e.message)}finally{on.disabled=off.disabled=false}};
}
async function history(){screen('history',`<div class="hero"><div class="eyebrow">Espace client</div><h1>Mes réservations</h1><p>Horaires affichés en heure de Tunis. Suivi actualisé toutes les 15 secondes.</p><button type="button" id="clientWashPush" class="outline">Activer les notifications de lavage</button></div><section class="card"><div class="formgrid"><label>Du<input type="date" id="from" value="${meta.now.date.slice(0,7)}-01"></label><label>Au<input type="date" id="to" value="${meta.now.date.slice(0,4)}-12-31"></label></div><div class="row toolbar"><button class="small outline" id="all">Tout l’historique</button><button class="small primary" id="print" disabled>Imprimer la sélection</button></div><div id="hist"></div></section>`);$('#clientWashPush').onclick=clientPushSettings;let rs=[],historyToken=0;async function load(){const token=++historyToken;try{const selectedIds=checked('.histcheck');const rows=await api('history?'+qs({from:val('#from')||'2000-01-01',to:val('#to')||'2099-12-31'}));if(page!=='history'||token!==historyToken||!$('#hist'))return;rs=rows;$('#hist').innerHTML=rs.map(r=>`<div class="history-item"><div class="row between"><label class="inlinecheck"><input type="checkbox" class="histcheck" value="${r.id}" ${selectedIds.includes(r.id)?'checked':''}>Réservation n° ${r.id}</label>${status(r)}</div><h3>${r.items.map(s=>esc(s.name)).join(' + ')}</h3><p>${esc(dateFmt(r.date))} · ${time(r.start)}–${time(r.start+r.duration)} · Piste ${r.lane}<br>${esc(r.vehicle)} ${r.notes?' · '+esc(r.notes):''}<br>Réservé le ${esc(created(r.created_at))}</p>${washDetails(r)}<div class="row between"><b class="price">${money(r.total)}</b><button class="small outline" data-receipt="${r.id}">Imprimer</button></div></div>`).join('')||'<div class="empty">Aucune réservation.</div>';$('#print').disabled=!checked('.histcheck').length;$('#hist').onchange=()=>$('#print').disabled=!checked('.histcheck').length;$('#hist').onclick=e=>{const b=e.target.closest('[data-receipt]');if(b)receipt(rs.filter(r=>r.id===+b.dataset.receipt))}}catch(e){err(e)}}$('#from').onchange=load;$('#to').onchange=load;$('#all').onclick=()=>{$('#from').value='';$('#to').value='';load()};$('#print').onclick=()=>receipt(rs.filter(r=>checked('.histcheck').includes(r.id)));load();refreshHistory=load;refreshTimer=setInterval(()=>{if(page==='history')load()},15000);}
const totals=(rs,es)=>{const revenue=rs.filter(r=>r.status==='confirmed').reduce((n,r)=>n+r.total,0),expenses=es.reduce((n,e)=>n+e.amount,0);return {revenue,expenses,net:revenue-expenses}};const kpis=(rs,es)=>{const t=totals(rs,es);return `<div class="grid kpis">${[['Chiffre d’affaires',t.revenue],['Dépenses',t.expenses],['Solde net',t.net]].map(([l,v])=>`<div class="card kpi"><div class="muted">${l}</div><div class="big">${money(v)}</div></div>`).join('')}</div>`};
function timeline(rs,bs,date){const n=meta.now;const position=(s,d)=>`left:${(s-510)/6}%;width:${d/6}%`;return `<div class="timelinewrap"><div class="timeline"><div class="ruler">${Array.from({length:11},(_,i)=>`<span style="left:${i*10}%">${time(510+60*i)}</span>`).join('')}</div>${[1,2].map(l=>`<div class="trackrow"><div class="tracklabel">Piste ${l}</div><div class="track">${rs.filter(r=>r.lane===l&&r.status==='confirmed').map(r=>`<button class="event" data-edit="${r.id}" style="${position(r.start,r.duration)}" title="${esc(r.name+' – '+r.items.map(s=>s.name).join(' + '))}"><b>${esc(r.name)}</b><br>${time(r.start)} · ${esc(r.items.map(s=>s.name).join(' + '))}</button>`).join('')}${bs.filter(b=>b.lane===l).map(b=>`<button class="event blocked" data-unblock="${b.id}" style="${position(b.start,b.duration)}" title="${esc(b.notes)}">Bloqué<br>${time(b.start)}</button>`).join('')}${date===n.date&&n.minute>=510&&n.minute<=1110?`<span class="line-now" style="left:${(n.minute-510)/6}%"></span>`:''}</div></div>`).join('')}</div></div>`}
async function dashboard(){try{meta=await api('meta');adminDate ||= meta.now.date;screen('admin',`<div class="hero row between"><div><div class="eyebrow">Administration</div><h1>Tableau de bord</h1><p>Planning quotidien · 2 pistes · 08:30–18:30 · Heure de Tunis</p></div><label>Journée<input id="adminDate" type="date" value="${adminDate}"></label></div><div id="dayContent"></div>`);$('#adminDate').onchange=()=>{adminDate=val('#adminDate');loadDay()};await loadDay();refreshTimer=setInterval(()=>{if(page==='admin'&&!modal)loadDay()},30000)}catch(e){err(e)}}
async function loadDay(){const token=++dayLoadToken,d=adminDate;try{const a=await api('admin/day?'+qs({date:d}));if(page!=='admin'||d!==adminDate||token!==dayLoadToken)return;adminData=a;meta.now=(await api('meta')).now;if(page!=='admin'||d!==adminDate||token!==dayLoadToken)return;$('#dayContent').innerHTML=`${kpis(a.reservations,a.expenses)}<section class="card"><div class="row between"><h2>Planning des pistes</h2><span class="tag">${a.closed?'Station fermée':'Station ouverte'}</span></div><div class="row toolbar"><button class="primary" id="add" ${a.closed?'disabled':''}>+ Réservation</button><button id="block" class="outline">Bloquer un créneau</button><button id="closeDay" class="outline">${a.closed?'Ouvrir cette journée':'Fermer cette journée'}</button></div>${timeline(a.reservations,a.blocks,d)}<p class="muted">Actualisation automatique toutes les 30 secondes · Cliquez sur un rendez-vous pour le modifier.</p></section><section class="card"><h2>Réservations de la journée (${a.reservations.length})</h2><div class="tablewrap"><table><thead><tr><th>Rendez-vous</th><th>Client / véhicule</th><th>Prestations</th><th>Total</th><th>Réservé le</th><th>Actions</th></tr></thead><tbody>${a.reservations.map(r=>`<tr><td>${time(r.start)}–${time(r.start+r.duration)}<br>Piste ${r.lane}<br>${status(r)}${washDetails(r)}</td><td><b>${esc(r.name)}</b><br>${esc(r.phone)}<br>${esc(r.vehicle)}${r.notes?'<br><i>'+esc(r.notes)+'</i>':''}</td><td>${r.items.map(s=>esc(s.name)).join('<br>')}</td><td><b>${money(r.total)}</b></td><td>${esc(created(r.created_at))}</td><td>${r.status==='confirmed'?`<button class="small outline" data-edit="${r.id}">Modifier</button> <button class="small danger" data-cancel="${r.id}">Annuler</button>`:''} <button class="small outline" data-print="${r.id}">Reçu</button>${washControls(r)}</td></tr>`).join('')}</tbody></table>${!a.reservations.length?'<div class="empty">Aucune réservation pour cette journée.</div>':''}</div></section><section class="card"><div class="row between"><h2>Dépenses quotidiennes</h2><button id="expense" class="outline">+ Dépense</button></div>${a.expenses.map(e=>`<div class="row between history-item"><span>${esc(e.label)}</span><b>${money(e.amount)}</b><button class="small danger" data-expense="${e.id}">Supprimer</button></div>`).join('')||'<div class="empty">Aucune dépense.</div>'}</section>`;$('#add').onclick=()=>adminBooking();$('#block').onclick=blockForm;$('#expense').onclick=expenseForm;$('#closeDay').onclick=async()=>{try{await api('admin/closure','POST',{date:d,closed:!a.closed});loadDay()}catch(e){err(e)}};$('#dayContent').onclick=async e=>{const b=e.target.closest('button');if(!b)return;const x=b.dataset;try{if(x.washStart||x.washRemaining||x.washFinish){const id=+(x.washStart||x.washRemaining||x.washFinish);return washAction(a.reservations.find(r=>r.id===id),x.washStart?'start':x.washRemaining?'remaining':'finish')}if(x.edit)adminBooking(a.reservations.find(r=>r.id===+x.edit));if(x.cancel&&confirm('Annuler cette réservation ?')){await api('admin/reservation','DELETE',{id:+x.cancel});loadDay()}if(x.unblock&&confirm('Débloquer ce créneau ?')){await api('admin/block','DELETE',{id:+x.unblock});loadDay()}if(x.expense&&confirm('Supprimer cette dépense ?')){await api('admin/expense','DELETE',{id:+x.expense});loadDay()}if(x.print)receipt(a.reservations.filter(r=>r.id===+x.print))}catch(e){err(e)}}}catch(e){err(e)}}
function openModal(title,html){closeModal();modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<section class="card" role="dialog" aria-modal="true"><div class="row between"><h2>${esc(title)}</h2><button class="small outline" id="modalClose">Fermer</button></div>${html}</section>`;document.body.append(modal);$('#modalClose').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal)closeModal()})}function closeModal(){modal?.remove();modal=null;availabilityToken++}
function adminBooking(r=null){const ss=adminData.services.filter(s=>s.active||r?.items.some(x=>x.id===s.id));openModal(r?'Modifier la réservation':'Nouvelle réservation',`<form id="adminForm" class="stack"><div class="formgrid"><label>Numéro de téléphone<input id="aPhone" type="tel" value="${esc(r?.phone)}" required></label><label>Nom du client<input id="aName" value="${esc(r?.name)}" required></label></div><div class="muted" id="lookup"></div><h3>Prestations</h3><div class="grid">${ss.map(s=>`<label class="inlinecheck"><input class="aservice" type="checkbox" value="${s.id}" ${r?.items.some(x=>x.id===s.id)?'checked':''}>${esc(s.name)} · ${money(s.price)}</label>`).join('')}</div><div class="formgrid"><label>Date<input type="date" id="aDate" value="${r?.date||adminDate}" required></label><label>Véhicule (modèle / matricule)<input id="aVehicle" value="${esc(r?.vehicle)}"></label></div><label>Remarque<textarea id="aNotes">${esc(r?.notes)}</textarea></label><div id="aSummary" class="muted"></div><div id="aSlots" class="slots"></div><label>Piste<select id="aLane"><option value="">Automatique</option></select></label><div class="error hidden" id="aError"></div><button id="aConfirm" class="primary" disabled>Enregistrer</button></form>`);let choice=null;let available=[];const renderLanes=(s,wanted)=>{$('#aLane').innerHTML='<option value="">Automatique</option>'+s.lanes.map(l=>`<option value="${l}" ${l===wanted?'selected':''}>Piste ${l}</option>`).join('')};async function load(){const token=++availabilityToken;const ids=checked('.aservice');choice=null;$('#aConfirm').disabled=true;if(!ids.length){$('#aSlots').innerHTML='';$('#aSummary').textContent='Choisissez une prestation.';return}try{const a=await api('availability?'+qs({date:val('#aDate'),services:ids.join(','),exclude:r?.id||0}));if(token!==availabilityToken||!modal)return;available=a.slots;const first=r?a.slots.find(s=>s.start===r.start&&val('#aDate')===r.date):null;choice=first?.start??null;$('#aSummary').textContent=money(a.total)+' · '+dur(a.duration)+(!a.slots.length&&a.next?' · Prochaine disponibilité : '+a.next.date+' '+time(a.next.start):'');$('#aSlots').innerHTML=a.slots.map(s=>`<button type="button" class="slot ${s.start===choice?'on':''}" data-start="${s.start}">${time(s.start)}<small>${s.lanes.length} piste(s)</small></button>`).join('')||'<span class="muted">Aucun créneau</span>';if(first)renderLanes(first,r?.lane);$('#aConfirm').disabled=choice===null}catch(e){if(token===availabilityToken)err(e,$('#aError'))}}$('#aSlots').onclick=e=>{const b=e.target.closest('[data-start]');if(!b)return;choice=+b.dataset.start;document.querySelectorAll('#aSlots .slot').forEach(x=>x.classList.toggle('on',x===b));renderLanes(available.find(s=>s.start===choice));$('#aConfirm').disabled=false};document.querySelectorAll('.aservice').forEach(x=>x.onchange=load);$('#aDate').onchange=load;$('#aPhone').onblur=async()=>{try{const p=val('#aPhone'),c=await api('admin/customer?'+qs({phone:p}));if(!modal||val('#aPhone')!==p)return;if(c){$('#aName').value=c.name;$('#lookup').textContent='Client trouvé : '+c.name}else{$('#lookup').textContent='Nouveau client – saisissez son nom.';$('#aName').value=''}}catch(e){if($('#lookup'))$('#lookup').textContent=e.message}};$('#adminForm').onsubmit=async e=>{e.preventDefault();if(choice===null)return;try{const data={id:r?.id,date:val('#aDate'),start:choice,lane:val('#aLane')||undefined,services:checked('.aservice'),name:val('#aName'),phone:val('#aPhone'),vehicle:val('#aVehicle'),notes:val('#aNotes')};await api(r?'admin/reservation':'reservations',r?'PUT':'POST',data);adminDate=data.date;closeModal();dashboard();toast('Réservation enregistrée')}catch(e){err(e,$('#aError'));load()}};load()}
function blockForm(){openModal('Bloquer un créneau',`<form class="stack" id="blockForm"><label>Date<input id="bDate" type="date" value="${adminDate}" required></label><div class="formgrid"><label>Heure de début<input id="bStart" type="time" value="08:30" min="08:30" max="18:29" required></label><label>Durée (minutes)<input id="bDuration" type="number" min="1" max="600" value="30" required></label><label>Piste<select id="bLane"><option value="1">Piste 1</option><option value="2">Piste 2</option></select></label></div><label>Motif<textarea id="bNotes"></textarea></label><div class="error hidden" id="bError"></div><button class="primary">Bloquer</button></form>`);$('#blockForm').onsubmit=async e=>{e.preventDefault();try{const [h,m]=val('#bStart').split(':').map(Number),date=val('#bDate');await api('admin/block','POST',{date,start:h*60+m,duration:+val('#bDuration'),lane:+val('#bLane'),notes:val('#bNotes')});adminDate=date;closeModal();dashboard();toast('Créneau bloqué')}catch(e){err(e,$('#bError'))}}}
function expenseForm(){openModal('Ajouter une dépense',`<form class="stack" id="expenseForm"><label>Date<input id="eDate" type="date" value="${adminDate}" required></label><label>Libellé<input id="eLabel" required></label><label>Montant (TND)<input id="eAmount" type="number" min="0" step="0.001" required></label><div class="error hidden" id="eError"></div><button class="primary">Enregistrer</button></form>`);$('#expenseForm').onsubmit=async e=>{e.preventDefault();try{const date=val('#eDate');await api('admin/expense','POST',{date,label:val('#eLabel'),amount:val('#eAmount')});adminDate=date;closeModal();dashboard()}catch(e){err(e,$('#eError'))}}}
function contactBatches(raw){
 const cards=raw.replace(/\r\n?/g,'\n').match(/^BEGIN:VCARD[ \t]*\n[\s\S]*?^END:VCARD[ \t]*(?=\n|$)/gmi)||[];
 if(!cards.length)throw Error('Aucun contact vCard valide trouvé dans ce fichier.');
 const batches=[];let batch=[],size=0;
 for(const card of cards){
  const lines=card.replace(/\n[ \t]/g,'').split('\n').filter(l=>/^(?:[\w-]+\.)?(?:FN|N|TEL)(?:;[^:]*)?:/i.test(l)&&l.length<=4096).map(l=>l.replace(/^[\w-]+\.(?=(?:FN|N|TEL)(?:;|:))/i,''));
  const clean='BEGIN:VCARD\n'+lines.join('\n')+'\nEND:VCARD\n';
  const bytes=JSON.stringify(clean).length*3;
  if(batch.length&&(batch.length>=200||size+bytes>200000)){batches.push({vcf:batch.join(''),count:batch.length});batch=[];size=0}
  batch.push(clean);size+=bytes;
 }
 if(batch.length)batches.push({vcf:batch.join(''),count:batch.length});
 return {total:cards.length,batches};
}
async function syncPhoneContacts(button,status,onDone){
 if(!navigator.contacts||typeof navigator.contacts.select!=='function'){status.textContent='La sélection directe des contacts n’est pas disponible dans ce navigateur. Ouvrez Eco’Lav dans Chrome sur Android, ou utilisez l’importation de fichier .vcf.';return}
 if(button.disabled)return;button.disabled=true;let done=0,imported=0,duplicates=0,invalid=0;
 try{
 const picked=await navigator.contacts.select(['name','tel'],{multiple:true});
 if(!picked.length){status.textContent='Aucun contact sélectionné.';return}
 const records=picked.map(c=>({name:String(c.name?.[0]||'').slice(0,200),tel:(Array.isArray(c.tel)?c.tel:[]).slice(0,20).map(t=>String(t).slice(0,100))}));
 if(!confirm('Importer '+records.length+' contact(s) sélectionné(s) dans le répertoire clients Eco’Lav ? Les contacts existants ne seront pas modifiés.')){status.textContent='Synchronisation annulée.';return}
 for(let i=0;i<records.length;i+=200){const batch=records.slice(i,i+200);const r=await api('admin/sync-contacts','POST',{contacts:batch});done+=batch.length;imported+=r.imported;duplicates+=r.duplicates;invalid+=r.invalid;status.textContent='Synchronisation : '+done+'/'+records.length+' contacts traités…'}
 status.textContent='Terminé : '+imported+' ajouté(s), '+duplicates+' déjà présent(s), '+invalid+' sans nom ou numéro tunisien valide.';toast('Synchronisation terminée.');if(onDone)await onDone();
 }catch(e){status.textContent='Synchronisation interrompue : '+e.message+(done?' — '+done+' contacts déjà traités.':'')+' Vous pouvez réessayer ou importer un fichier .vcf.'}finally{button.disabled=false}
}

function contacts(){
 screen('contacts',`<div class="hero row between"><div><div class="eyebrow">Administration · Répertoire</div><h1>Contacts clients</h1><p>Retrouvez les clients inscrits et les contacts importés.</p></div><button type="button" class="outline" id="contactsBack">Retour au planning</button></div><section class="card stack"><div class="row between"><h2 id="contactsCount">Répertoire clients</h2><button type="button" class="outline" id="contactsImport">Importer un fichier</button></div><div class="notice stack"><button type="button" class="primary" id="syncPhone">Synchroniser les contacts du téléphone</button><small>Choisissez les contacts clients à importer depuis votre téléphone. Aucun contact existant ne sera écrasé.</small><div id="syncPhoneStatus" role="status" aria-live="polite"></div></div><form id="contactSearch" class="stack"><label>Rechercher un contact<input id="contactQuery" type="search" maxlength="150" placeholder="Nom, téléphone, véhicule ou adresse"></label><div class="row"><button type="submit" class="primary">Rechercher</button><button type="button" class="outline" id="contactClear">Effacer</button></div></form><div id="contactResults" aria-live="polite">Chargement…</div><div class="row between"><button type="button" class="outline" id="contactsPrev" disabled>← Précédent</button><span id="contactsPage" class="muted"></span><button type="button" class="outline" id="contactsNext" disabled>Suivant →</button></div></section>`);
 const root=$('#contactResults');let current=1,query='',request=0;
 async function load(wanted=1){const seq=++request;root.textContent='Chargement…';$('#contactsPrev').disabled=$('#contactsNext').disabled=true;try{
 const r=await api('admin/contacts?'+qs({search:query,page:wanted}));if(seq!==request||page!=='contacts'||!root.isConnected)return;
 current=r.page;$('#contactsCount').textContent=`${r.total} contact(s) enregistré(s)`;$('#contactsPage').textContent=`Page ${r.page} / ${r.pages} · ${r.filtered} résultat(s)`;
 root.innerHTML=r.contacts.map(c=>`<article class="contact-entry"><div class="row between"><strong>${esc(c.name)}</strong><small class="contact-state ${c.activated?'active':''}">${c.activated?'Compte actif':'À activer'}</small></div><a class="contact-phone" href="tel:+216${esc(c.phone)}">${esc(c.phone.replace(/^(\d{2})(\d{3})(\d{3})$/,'$1 $2 $3'))}</a>${c.vehicles?.length?c.vehicles.map(v=>`<div class="muted">Véhicule : ${esc(v.model)} · ${esc(v.plate)}</div>`).join(''):c.vehicle?`<div class="muted">Véhicule : ${esc(c.vehicle)} (à compléter)</div>`:''}${c.address?`<div class="muted">Adresse : ${esc(c.address)}</div>`:''}</article>`).join('')||'<div class="notice">Aucun contact trouvé.</div>';
 $('#contactsPrev').disabled=r.page<=1;$('#contactsNext').disabled=r.page>=r.pages;
 }catch(e){if(seq===request&&root.isConnected)root.textContent=e.message}}
 $('#contactsBack').onclick=dashboard;$('#contactsImport').onclick=settings;$('#syncPhone').onclick=()=>syncPhoneContacts($('#syncPhone'),$('#syncPhoneStatus'),()=>load(1));$('#contactSearch').onsubmit=e=>{e.preventDefault();query=val('#contactQuery').trim();load(1)};$('#contactClear').onclick=()=>{$('#contactQuery').value='';query='';load(1)};$('#contactsPrev').onclick=()=>load(current-1);$('#contactsNext').onclick=()=>load(current+1);load();
}
async function settings(){try{const a=await api('admin/day?'+qs({date:adminDate||meta.now.date}));screen('settings',`<div class="hero row between"><div><div class="eyebrow">Administration</div><h1>Paramètres</h1></div><button id="back" class="outline">Retour au planning</button></div><section class="card"><div class="row between"><h2>Gestion des prestations</h2><button class="primary" id="newService">+ Ajouter</button></div>${a.services.map(s=>`<div class="row between history-item"><div><b>${esc(s.name)}</b><p>${money(s.price)} · ${dur(s.duration)} ${s.active?'':'· désactivée'}</p></div><div class="row"><button data-service-edit="${s.id}" class="outline small">Modifier</button>${s.active?`<button data-service-del="${s.id}" class="danger small">Désactiver</button>`:''}</div></div>`).join('')}</section><section class="card"><h2>Activation / réinitialisation client</h2><p>Vérifiez l’identité du client avant de générer un code personnel. Cette opération révoque ses anciennes connexions et son ancien mot de passe. Le code expire après 48 heures.</p><form id="activationAdmin" class="stack"><label>Téléphone du client<input id="activationPhone" type="tel" required></label><label>Code d’activation personnalisé (facultatif)<input id="activationCustomCode" type="text" inputmode="numeric" pattern="[0-9]{6,8}" maxlength="8" autocomplete="off" placeholder="6 à 8 chiffres"></label><p class="muted">Choisissez un code personnel simple à communiquer, ou laissez le champ vide pour générer automatiquement 6 chiffres. Évitez les suites évidentes et les codes déjà utilisés.</p><button class="primary">Enregistrer le code d’activation</button></form></section><section class="card"><div class="row between"><h2>Importer les contacts</h2><button type="button" class="outline" id="viewContacts">Voir la liste des contacts</button></div><div class="notice stack"><button type="button" class="primary" id="syncPhoneSettings">Synchroniser les contacts du téléphone</button><small>Sélection manuelle des contacts clients dans le carnet d’adresses du téléphone.</small><div id="syncPhoneSettingsStatus" role="status" aria-live="polite"></div></div><p>Fichier vCard (.vcf), jusqu’à 50 Mo. Importation par lots, sans photos. Importez uniquement les contacts clients de la station. Les numéros déjà enregistrés sont ignorés.</p><form id="import" class="stack"><input id="vcf" type="file" accept=".vcf,.vcard,text/vcard" required><button class="primary" type="submit">Importer</button><div id="importStatus" class="notice" role="status" aria-live="polite">Sélectionnez votre fichier de contacts.</div></form></section>`);$('#back').onclick=dashboard;$('#newService').onclick=()=>serviceForm();$('#viewContacts').onclick=contacts;$('#syncPhoneSettings').onclick=()=>syncPhoneContacts($('#syncPhoneSettings'),$('#syncPhoneSettingsStatus'));app.onclick=async e=>{if(page!=='settings')return;const b=e.target.closest('button');if(!b)return;if(b.dataset.serviceEdit)serviceForm(a.services.find(s=>s.id===+b.dataset.serviceEdit));if(b.dataset.serviceDel&&confirm('Désactiver cette prestation ?')){try{await api('admin/service','DELETE',{id:+b.dataset.serviceDel});settings()}catch(e){err(e)}}};$('#activationAdmin').onsubmit=async e=>{e.preventDefault();if(!confirm('Confirmez-vous avoir vérifié l’identité du client ? Son ancien mot de passe sera désactivé.'))return;try{const r=await api('admin/activation','POST',{phone:val('#activationPhone'),code:val('#activationCustomCode')});openModal('Code personnel',`<p>Communiquez ce code uniquement au client identifié. Valable 48 heures, utilisable une seule fois.</p><label>Code<input readonly value="${esc(r.code)}" id="generatedCode"></label><p class="muted">Le client entre son numéro, puis ce code pour activer son compte. Pour changer le code, enregistrez-en un nouveau pour le même numéro : l’ancien code sera invalidé.</p>`);$('#generatedCode').select()}catch(e){err(e)}};$('#import').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector('button'),file=form.querySelector('#vcf').files[0],status=form.querySelector('#importStatus');if(btn.disabled||!file)return;btn.disabled=true;let imported=0,skipped=0,done=0,total=0;try{if(file.size>50*1024*1024)throw Error('Fichier supérieur à 50 Mo. Exportez vos contacts en plusieurs fichiers.');status.textContent='Lecture du fichier…';const parsed=contactBatches(await file.text());total=parsed.total;for(const batch of parsed.batches){status.textContent=`Importation : ${done}/${total} contacts…`;const r=await api('admin/import','POST',{vcf:batch.vcf});imported+=r.imported;skipped+=r.skipped;done+=batch.count;status.textContent=`Importation : ${done}/${total} · ${imported} importé(s), ${skipped} ignoré(s).`;}status.textContent=`Terminé : ${imported} contact(s) importé(s), ${skipped} ignoré(s) sur ${total}.`;toast('Importation terminée.')}catch(e){status.textContent=`Importation interrompue : ${e.message} ${done?done+' contacts déjà traités. ':''}Vous pouvez relancer le même fichier : les doublons seront ignorés.`;}finally{btn.disabled=false}}}catch(e){err(e)}}
function serviceForm(s){openModal(s?'Modifier la prestation':'Ajouter une prestation',`<form id="serviceForm" class="stack"><label>Nom<input id="sName" value="${esc(s?.name)}" required></label><label>Prix (TND)<input id="sPrice" type="number" min="0" step="0.001" value="${s?s.price/1000:''}" required></label><label>Durée (minutes)<input id="sDuration" type="number" min="1" max="600" value="${s?.duration||30}" required></label><div id="sError" class="error hidden"></div><button class="primary">Enregistrer</button></form>`);$('#serviceForm').onsubmit=async e=>{e.preventDefault();try{await api('admin/service','POST',{id:s?.id,name:val('#sName'),price:val('#sPrice'),duration:val('#sDuration')});closeModal();settings()}catch(e){err(e,$('#sError'))}}}
function adminHistory(){
 screen('adminHistory',`<div class="hero row between"><div><div class="eyebrow">Administration</div><h1>Historique des réservations</h1><p>Recherchez les réservations passées et annulées de tous les clients.</p></div><button type="button" class="outline" id="historyBack">Retour au planning</button></div><section class="card stack"><form id="adminHistorySearch" class="stack"><div class="formgrid"><label>Du<input type="date" id="histFrom"></label><label>Au<input type="date" id="histTo"></label></div><label>Rechercher<input id="histQuery" type="search" maxlength="150" placeholder="Client, téléphone, véhicule ou n° de réservation"></label><button class="primary" type="submit">Afficher</button></form><p class="muted">La suppression est définitive et modifie les rapports financiers. Annulez d’abord les rendez-vous à venir ou en cours.</p><div class="notice stack"><label class="inlinecheck"><input id="histSelectAll" type="checkbox" disabled> Tout sélectionner sur cette page</label><div class="row between" style="flex-wrap:wrap"><span id="histSelectedCount">0 réservation sélectionnée</span><div class="row" style="flex-wrap:wrap"><button class="small outline" type="button" id="histClearSelection" disabled>Tout désélectionner</button><button class="danger" type="button" id="histDeleteSelected" disabled>Supprimer la sélection</button></div></div></div><div id="adminHistResults" aria-live="polite">Chargement…</div><div class="row between"><button type="button" class="outline" id="histPrev" disabled>← Précédent</button><span id="histPage" class="muted"></span><button type="button" class="outline" id="histNext" disabled>Suivant →</button></div></section>`);
 const root=$('#adminHistResults');let rows=[],current=1,seq=0,busy=false,loading=false,filters={from:'',to:'',search:''};const selection=new Set();
 function updateSelection(){if(!root.isConnected)return;const eligible=rows.filter(r=>r.can_delete);const all=$('#histSelectAll');const count=eligible.filter(r=>selection.has(r.id)).length;all.checked=eligible.length>0&&count===eligible.length;all.indeterminate=count>0&&count<eligible.length;all.disabled=busy||loading||!eligible.length;$('#histSelectedCount').textContent=selection.size+' réservation(s) sélectionnée(s)';$('#histDeleteSelected').disabled=busy||loading||!selection.size;$('#histClearSelection').disabled=busy||!selection.size;root.querySelectorAll('[data-hist-select]').forEach(x=>{x.checked=selection.has(+x.dataset.histSelect);x.disabled=busy||loading});}
 async function remove(ids){if(busy||loading||!ids.length)return;if(!confirm('Supprimer définitivement '+ids.length+' réservation(s) ? Elles disparaîtront du planning, de l’historique client et des rapports financiers. Cette action est irréversible.'))return;busy=true;updateSelection();try{const r=await api('admin/history','DELETE',{ids,confirm:true});ids.forEach(id=>selection.delete(id));if(root.isConnected){await load(current);toast(r.deleted+' réservation(s) supprimée(s).')}}catch(e){if(root.isConnected)err(e)}finally{busy=false;updateSelection()}}
 async function load(wanted=1){const token=++seq;loading=true;rows=[];updateSelection();root.textContent='Chargement…';$('#histPrev').disabled=$('#histNext').disabled=true;try{const r=await api('admin/history?'+qs({...filters,page:wanted}));if(!root.isConnected||token!==seq)return;rows=r.reservations;current=r.page;$('#histPage').textContent=`Page ${r.page}/${r.pages} · ${r.total} réservation(s)`;root.innerHTML=rows.map(r=>`<article class="history-item"><div class="row between">${r.can_delete?`<label class="inlinecheck"><input type="checkbox" data-hist-select="${r.id}" ${selection.has(r.id)?'checked':''}> Réservation n° ${r.id}</label>`:`<strong>Réservation n° ${r.id}</strong>`}${status(r)}</div><h3>${esc(r.name)} · ${esc(r.phone)}</h3><p>${esc(dateFmt(r.date))} · ${time(r.start)}–${time(r.start+r.duration)} · Piste ${r.lane}<br>${esc(r.vehicle)}<br>${r.items.map(x=>esc(x.name)).join(' + ')}</p><div class="row between"><b class="price">${money(r.total)}</b><div class="row" style="flex-wrap:wrap"><button class="small outline" data-hist-print="${r.id}">Reçu</button>${r.can_delete?`<button class="small danger" data-hist-delete="${r.id}">Supprimer définitivement</button>`:`<button class="small outline" data-hist-day="${esc(r.date)}">Voir au planning</button>`}</div></div></article>`).join('')||'<div class="empty">Aucune réservation trouvée.</div>';$('#histPrev').disabled=r.page<=1;$('#histNext').disabled=r.page>=r.pages;}catch(e){if(root.isConnected&&seq===token)root.textContent=e.message}finally{if(token===seq){loading=false;updateSelection()}}}
 $('#historyBack').onclick=dashboard;$('#adminHistorySearch').onsubmit=e=>{e.preventDefault();if(busy)return;selection.clear();filters={from:val('#histFrom'),to:val('#histTo'),search:val('#histQuery')};load(1)};$('#histPrev').onclick=()=>{if(!busy)load(current-1)};$('#histNext').onclick=()=>{if(!busy)load(current+1)};
 $('#histSelectAll').onchange=e=>{for(const r of rows.filter(r=>r.can_delete)){if(e.target.checked){if(selection.size<500)selection.add(r.id)}else selection.delete(r.id)}if(selection.size>=500)toast('Maximum : 500 réservations par suppression.');updateSelection()};$('#histClearSelection').onclick=()=>{selection.clear();updateSelection()};$('#histDeleteSelected').onclick=()=>remove([...selection]);root.onchange=e=>{const x=e.target.closest('[data-hist-select]');if(!x||busy)return;const id=+x.dataset.histSelect;if(x.checked){if(selection.size>=500){toast('Maximum : 500 réservations par suppression.')}else selection.add(id)}else selection.delete(id);updateSelection()};
 root.onclick=async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.histPrint){receipt(rows.filter(r=>r.id===+b.dataset.histPrint));return}if(b.dataset.histDay){adminDate=b.dataset.histDay;dashboard();return}const id=+b.dataset.histDelete;if(!id||busy)return;await remove([id])};
 load();
}
async function reports(){const today=meta.now.date;screen('reports',`<div class="hero row between"><div><div class="eyebrow">Administration</div><h1>Rapports financiers</h1></div><button id="back" class="outline">Retour au planning</button></div><section class="card"><div class="formgrid"><label>Du<input type="date" id="rf" value="${today.slice(0,7)}-01"></label><label>Au<input type="date" id="rt" value="${today}"></label></div><div class="row toolbar"><button class="primary" id="loadReport">Afficher</button><button class="outline" id="dayReport">Aujourd’hui</button><button class="outline" id="printReport">Imprimer / PDF</button></div></section><div id="report"></div>`);$('#back').onclick=dashboard;$('#printReport').onclick=()=>window.print();$('#dayReport').onclick=()=>{$('#rf').value=today;$('#rt').value=today;load()};async function load(){try{const a=await api('admin/reports?'+qs({from:val('#rf'),to:val('#rt')}));if(page!=='reports')return;const services={},days={};for(const r of a.reservations){days[r.date]??={r:0,e:0};days[r.date].r+=r.total;for(const s of r.items){services[s.name]??={n:0,p:0};services[s.name].n++;services[s.name].p+=s.price}}for(const e of a.expenses){days[e.date]??={r:0,e:0};days[e.date].e+=e.amount}$('#report').innerHTML=kpis(a.reservations,a.expenses)+`<section class="card"><h2>Par prestation</h2><div class="tablewrap"><table><thead><tr><th>Prestation</th><th>Nombre</th><th>Recettes</th></tr></thead><tbody>${Object.entries(services).map(([n,s])=>`<tr><td>${esc(n)}</td><td>${s.n}</td><td>${money(s.p)}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><h2>Détail journalier</h2><div class="tablewrap"><table><thead><tr><th>Date</th><th>Recettes</th><th>Dépenses</th><th>Net</th></tr></thead><tbody>${Object.entries(days).sort().map(([d,s])=>`<tr><td>${d}</td><td>${money(s.r)}</td><td>${money(s.e)}</td><td>${money(s.r-s.e)}</td></tr>`).join('')}</tbody></table></div></section>`}catch(e){err(e)}}$('#loadReport').onclick=load;load()}
function pushTimeout(p,ms,message){let timer;return Promise.race([p,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error(message)),ms)})]).finally(()=>clearTimeout(timer))}
let workerRegistration;
function registerPushWorker(){if(!('serviceWorker' in navigator))return Promise.reject(Error('Ce navigateur ne prend pas en charge les notifications.'));if(!workerRegistration)workerRegistration=pushTimeout(navigator.serviceWorker.register('/sw.js',{scope:'/'}),10000,'Installation du service de notification trop longue.').catch(e=>{workerRegistration=null;throw e});return workerRegistration}
async function pushSettings(){
openModal('Notifications push',`<p>Recevez une alerte lors de chaque nouvelle réservation client. Sur Android, utilisez Google Chrome et autorisez les notifications. Sur iPhone, ouvrez l’application installée depuis Safari.</p><div id="pushState" class="notice" role="status">Vérification…</div><div class="row"><button id="enablePush" class="primary" disabled>Activer</button><button id="disablePush" class="outline" disabled>Désactiver</button><button id="testPush" class="outline" disabled>Tester</button><button id="retryPush" class="outline" hidden>Réessayer</button></div>`);
const state=$('#pushState'),enable=$('#enablePush'),disable=$('#disablePush'),test=$('#testPush'),retry=$('#retryPush');
const show=t=>{if(state.isConnected)state.textContent=t};const busy=on=>{enable.disabled=on;disable.disabled=on;test.disabled=on};let reg,sub;
retry.onclick=()=>{closeModal();pushSettings()};
if(!window.isSecureContext||!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window)){show('Notifications non prises en charge dans ce navigateur. Ouvrez https://expert-ecolav.onrender.com directement dans Google Chrome (Android) ou Safari (iPhone).');return}
try{
reg=await registerPushWorker();reg=await pushTimeout(navigator.serviceWorker.ready,10000,'Le service de notification ne démarre pas.');
if(!state.isConnected)return;
sub=await pushTimeout(reg.pushManager.getSubscription(),8000,'Impossible de vérifier l’abonnement.');
show(Notification.permission==='denied'?'Notifications bloquées. Dans Chrome, ouvrez Paramètres > Paramètres des sites > Notifications, autorisez Eco’Lav et réessayez.':sub?'Abonnement présent. Appuyez sur Activer pour le synchroniser avec la station.':'Notifications non activées. Appuyez sur Activer.');
enable.disabled=false;disable.disabled=!sub;test.disabled=!sub;
enable.onclick=async()=>{busy(true);show('Activation en cours…');try{
if(await Notification.requestPermission()!=='granted')throw Error('Autorisation refusée. Autorisez les notifications de ce site dans les paramètres de Chrome et du téléphone.');
const key=Uint8Array.from(atob(meta.vapid.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(meta.vapid.length/4)*4,'=')),c=>c.charCodeAt(0));
sub=await pushTimeout(reg.pushManager.getSubscription(),8000,'Vérification de l’abonnement impossible.')||await pushTimeout(reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key}),18000,'Abonnement impossible. Essayez dans Google Chrome avec les services Google Play activés.');
await api('admin/push','POST',sub.toJSON());show('Notifications activées sur cet appareil. Appuyez sur Tester pour vérifier la réception.');
}catch(e){show(e.message)}finally{enable.disabled=false;disable.disabled=!sub;test.disabled=!sub}};
disable.onclick=async()=>{busy(true);try{if(sub){await api('admin/push','DELETE',{endpoint:sub.endpoint});await sub.unsubscribe();sub=null}show('Notifications désactivées.')}catch(e){show(e.message)}finally{enable.disabled=false;disable.disabled=!sub;test.disabled=!sub}};
test.onclick=async()=>{busy(true);show('Envoi de la notification de test…');try{if(!sub)throw Error('Activez les notifications avant le test.');const r=await api('admin/push-test','POST',{endpoint:sub.endpoint});show(r.sent>0?'Notification envoyée au service push. Vérifiez la barre de notifications du téléphone.':'La notification n’a pas pu être envoyée. Désactivez puis réactivez les notifications.')}catch(e){show(e.message)}finally{enable.disabled=false;disable.disabled=!sub;test.disabled=!sub}};
}catch(e){show('Impossible d’initialiser les notifications : '+e.message+' Ouvrez le site directement dans Google Chrome, puis réessayez.');retry.hidden=false;workerRegistration=null;}
}
document.querySelector('footer a[href="/?admin=1"]')?.addEventListener('click',e=>{e.preventDefault();if(session.role==='admin')dashboard();else login(true)});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&page==='history')refreshHistory?.();else if(!document.hidden&&page==='admin'&&!modal)loadDay()});
async function init(){try{meta=await api('meta');session=await api('session');if(!session.role&&mobileToken)saveMobileToken(null);if('serviceWorker'in navigator)registerPushWorker().catch(()=>{});const entry=new URLSearchParams(location.search);if(entry.get('admin')==='1'&&session.role!=='admin')login(true);else if(entry.get('client')==='1'&&session.role!=='client')login();else if(session.role==='admin')dashboard();else if(session.role==='client'){if(entry.get('history')==='1')history();else services()}else home()}catch(e){app.innerHTML=`<div class="card error">${esc(e.message)}<p>Rechargez la page.</p></div>`}}init();
